"""Bundle the launcher into one installer transferable over authenticated SSH."""
from pathlib import Path

root = Path(__file__).resolve().parent
launcher = (root / 'gpu-dashboard').read_text()
prefix = '''#!/bin/bash
# Generated by build_installer.py. Execute on the Mac, not on Spartan.
set -euo pipefail
if [ "$(uname -s)" != Darwin ]; then
    printf '%s\\n' '请在 Mac 本地终端执行安装命令；未修改当前机器。' >&2
    exit 1
fi
dashboard_bin="$HOME/.local/bin"
mkdir -p "$dashboard_bin"
dashboard_tmp=$(mktemp "$dashboard_bin/.gpu-dashboard-install.XXXXXX")
trap 'rm -f "$dashboard_tmp"' EXIT
cat > "$dashboard_tmp" <<'GPU_DASHBOARD_LAUNCHER_EOF'
'''
suffix = '''GPU_DASHBOARD_LAUNCHER_EOF
/bin/bash -n "$dashboard_tmp"
chmod 755 "$dashboard_tmp"
dashboard_command="$dashboard_bin/gpu-dashboard"
if [ -e "$dashboard_command" ] && ! cmp -s "$dashboard_tmp" "$dashboard_command"; then
    cp -p "$dashboard_command" "$dashboard_command.backup-$(date +%Y%m%dT%H%M%S)-$$"
fi
mv -f "$dashboard_tmp" "$dashboard_command"
for dashboard_rc in "$HOME/.zprofile" "$HOME/.zshrc"; do
    if ! grep -Fq '# gpu-dashboard PATH' "$dashboard_rc" 2>/dev/null; then
        cat >> "$dashboard_rc" <<'GPU_DASHBOARD_PATH_EOF'

# gpu-dashboard PATH
case ":$PATH:" in
    *":$HOME/.local/bin:"*) ;;
    *) export PATH="$HOME/.local/bin:$PATH" ;;
esac
GPU_DASHBOARD_PATH_EOF
    fi
done
printf '%s\\n' '已安装：~/.local/bin/gpu-dashboard' \\
    '新开一个终端后运行：gpu-dashboard' \\
    '当前终端立即使用：~/.local/bin/gpu-dashboard'
'''
(root / 'install-macos.sh').write_text(prefix + launcher + suffix)
